// Generated by GitHub Copilot
import { useState } from 'react';
import {
  createAck,
  createPaymentIntent,
  decodeAck,
  decodeIntent,
  encodeMessage,
  isExpired
} from '../../protocol/codec';
import { applyAck, listAll, upsertFromIntent, wasSeen } from '../../storage/ledger';
import { logger } from '../logger';

/**
 * Demo loopback mode: ejecuta el flujo Cobrar → Pagar → Ack en memoria, sin BLE.
 * Sirve para probar protocolo, hashing, idempotencia, TTL y ledger sin hardware.
 */
export function DemoMode() {
  const [running, setRunning] = useState(false);
  const [result, setResult] = useState<string>('');

  async function runHappyPath() {
    setRunning(true);
    setResult('');
    try {
      logger.info('system', '— DEMO loopback (happy path) —');
      const intent = await createPaymentIntent({
        amount: 1500,
        currency: 'ARS',
        ttlMs: 60_000,
        memo: 'demo loopback'
      });
      await upsertFromIntent(intent, 'receiver', 'CREATED', 'demo intent creado');

      // Simula transmisión BLE: encode → "tx" → decode.
      const wire = encodeMessage(intent);
      logger.info('protocol', `wire size: ${wire.byteLength} bytes`);
      const received = await decodeIntent(wire);
      if (received.tx_id !== intent.tx_id) throw new Error('tx_id mismatch tras decode');
      if (isExpired(received)) throw new Error('intent expirado en demo (no debería)');

      await upsertFromIntent(received, 'payer', 'CREATED', 'demo intent recibido');

      const ack = await createAck(received, 'OK');
      const ackWire = encodeMessage(ack);
      const receivedAck = await decodeAck(ackWire);
      const updated = await applyAck(receivedAck, 'demo ack aplicado');

      setResult(`OK · tx_id=${intent.tx_id} · status=${updated?.status}`);
      logger.info('system', `DEMO OK status=${updated?.status}`);
    } catch (e) {
      const msg = (e as Error).message;
      logger.error('system', `DEMO error: ${msg}`);
      setResult(`ERROR: ${msg}`);
    } finally {
      setRunning(false);
    }
  }

  async function runIdempotency() {
    setRunning(true);
    setResult('');
    try {
      logger.info('system', '— DEMO idempotencia —');
      const intent = await createPaymentIntent({ amount: 100, currency: 'ARS', ttlMs: 60_000 });
      await upsertFromIntent(intent, 'receiver', 'CREATED', 'idempot test');
      const seenFirst = await wasSeen(intent.tx_id);
      // Re-publicar el mismo intent: tx_id ya visto.
      await upsertFromIntent(intent, 'receiver', 'CREATED', 'idempot test (replay)');
      const seenSecond = await wasSeen(intent.tx_id);
      setResult(`seen tras 1ra: ${seenFirst} · seen tras 2da: ${seenSecond} (esperado: true/true)`);
    } catch (e) {
      setResult(`ERROR: ${(e as Error).message}`);
    } finally {
      setRunning(false);
    }
  }

  async function runTtl() {
    setRunning(true);
    setResult('');
    try {
      logger.info('system', '— DEMO TTL vencido —');
      const intent = await createPaymentIntent({ amount: 200, currency: 'ARS', ttlMs: 1 });
      await new Promise((r) => setTimeout(r, 1100));
      const expired = isExpired(intent, Date.now(), 0);
      setResult(`isExpired=${expired} (esperado: true)`);
    } catch (e) {
      setResult(`ERROR: ${(e as Error).message}`);
    } finally {
      setRunning(false);
    }
  }

  async function runHashTamper() {
    setRunning(true);
    setResult('');
    try {
      logger.info('system', '— DEMO hash tamper —');
      const intent = await createPaymentIntent({ amount: 300, currency: 'ARS', ttlMs: 60_000 });
      const wire = encodeMessage(intent);
      // Alterar un byte y reesperar decodificación → debe fallar por hash inválido.
      const tampered = new Uint8Array(wire);
      tampered[10] = tampered[10] ^ 0x01;
      try {
        await decodeIntent(tampered);
        setResult('ERROR: debería haber rechazado payload alterado');
      } catch (err) {
        setResult(`OK · rechazo esperado: ${(err as Error).message}`);
      }
    } catch (e) {
      setResult(`ERROR: ${(e as Error).message}`);
    } finally {
      setRunning(false);
    }
  }

  async function showCount() {
    const all = await listAll();
    setResult(`Ledger: ${all.length} registros`);
  }

  return (
    <div className="card">
      <h2>Demo (loopback, sin BLE)</h2>
      <p className="muted">
        Ejecuta el flujo en memoria para validar protocolo, hash, idempotencia y TTL.
        Útil cuando todavía no hay relay físico.
      </p>
      <div className="row">
        <button className="primary" onClick={runHappyPath} disabled={running}>
          Happy path (Cobrar→Pagar→Ack)
        </button>
        <button className="secondary" onClick={runIdempotency} disabled={running}>
          Idempotencia
        </button>
        <button className="secondary" onClick={runTtl} disabled={running}>
          TTL vencido
        </button>
        <button className="secondary" onClick={runHashTamper} disabled={running}>
          Hash tamper
        </button>
        <button className="secondary" onClick={showCount} disabled={running}>
          Contar ledger
        </button>
      </div>
      {result && (
        <p className="muted" aria-live="polite" style={{ marginTop: 12 }}>
          <strong>Resultado:</strong> {result}
        </p>
      )}
    </div>
  );
}
